mapper.insert:
INSERT INTO t_xwyy_assist_requirement ( schedule_date, big_roll_code, day_plan_qty, night_plan_qty, today_stock, day_Out, fac5_class1_plan, fac5_class2_plan, fac5_class3_plan, remark, del_flag, create_by, create_time ) VALUES
( #{item.scheduleDate, jdbcType=DATE}, #{item.bigRollCode,jdbcType=VARCHAR}, #{item.dayPlanQty, jdbcType=DOUBLE}, #{item.nightPlanQty, jdbcType=DOUBLE}, #{item.todayStock, jdbcType=DOUBLE}, #{item.dayOut, jdbcType=DOUBLE}, #{item.fac5Class1Plan, jdbcType=DOUBLE}, #{item.fac5Class2Plan, jdbcType=DOUBLE}, #{item.fac5Class3Plan, jdbcType=DOUBLE}, #{item.remark,jdbcType=VARCHAR}, '0', #{item.createBy,jdbcType=VARCHAR}, NOW() )
ON DUPLICATE KEY UPDATE day_plan_qty = VALUES(day_plan_qty), night_plan_qty = VALUES(night_plan_qty), today_stock = VALUES(today_stock), day_Out = VALUES(day_Out), fac5_class1_plan = VALUES(fac5_class1_plan), fac5_class2_plan = VALUES(fac5_class2_plan), fac5_class3_plan = VALUES(fac5_class3_plan), remark = VALUES(remark), update_by = VALUES(create_by), update_time = NOW();

